const rate=country==='FR'?0:count>=4?.2:count===3?.15:count===2?.1:0;
const sums={};for(const x of items){const e=editions.find(e=>e[0]===x.edition);sums[e[3]]=(sums[e[3]]||0)+e[2]*x.qty;}
dialog.innerHTML=`<div class="cart-head"><h2 id="bcCartTitle">Votre panier</h2><button class="cart-close" data-close aria-label="Fermer le panier">×</button></div><p class="cart-muted">Collection imprimée en préparation · sélection et estimation de lancement.</p>${items.length?items.map((x,i)=>`<article class="cart-item"><p class="cart-title">${esc(x.title)}</p><label>Collection envisagée<select data-edition="${i}" aria-label="Édition de ${esc(x.title)}">${editions.filter(e=>choices(x.slug).includes(e[0])).map(e=>`<option value="${e[0]}" ${x.edition===e[0]?'selected':''}>${e[1]} · à partir de ${money(e[2],e[3])}</option>`).join('')}</select></label><div class="cart-row"><button data-qty="${i}" data-delta="-1" aria-label="Réduire la quantité de ${esc(x.title)}" ${x.qty===1?'disabled':''}>−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Augmenter la quantité de ${esc(x.title)}" ${x.qty===99?'disabled':''}>+</button><button class="cart-remove" data-remove="${i}">Retirer</button></div></article>`).join(''): '<p>Votre panier est vide. Ajoutez un livre depuis sa fiche.</p>'}${items.length?`<label>Pays de livraison envisagé<select id="bcCartCountry"><option value="">Choisir un pays</option>${markets.map(m=>`<option value="${m[0]}" ${country===m[0]?'selected':''}>${m[1]}</option>`).join('')}</select></label><div class="cart-estimate"><strong>${count} livre${count>1?'s':''} · remise estimée ${Math.round(rate*100)} %</strong>${Object.entries(sums).map(([cur,sum])=>`<p>Sous-total indicatif : ${money(sum,cur)}</p><p>Remise simulée : −${money(Math.round(sum*rate),cur)}</p><p class="cart-total">À partir de ${money(sum-Math.round(sum*rate),cur)}</p>`).join('')}</div><p class="cart-muted">Estimation avant taxes. Le prix et la disponibilité de chaque édition ainsi que la livraison restent à confirmer. Les devises sont présentées séparément. Aucun paiement ni réservation n’est effectué.${country==='FR'?' Les réductions sont suspendues pour la France dans l’attente de validation des règles du prix du livre.':' Remise simulée pour une seule commande à une même adresse.'}</p><button class="cart-primary" disabled>Paiement groupé en préparation</button>`:''}<p class="cart-muted">Votre sélection est conservée sur cet appareil.</p>`;
