add.onclick=()=>{const base=window.bookclassicsLaunchTitlePrices?.[slug]?.[0]||'pb';const found=items.find(x=>x.slug===slug&&x.edition===base);if(found&&found.qty<99)found.qty++;else if(!found)items.push({slug,title,edition:base,qty:1});const stored=save();render();status.textContent=stored?'Livre ajouté à votre sélection. Choisissez l’édition dans le panier.':'Livre ajouté pour cette visite. La sauvegarde sur cet appareil est indisponible.';dialog.showModal();};
