(()=>{'use strict';
const prices=window.bookclassicsLaunchTitlePrices||{};
const style=document.createElement('style');style.textContent='.bc-title-priced .info{gap:0!important}.bc-card-starting-price{display:block!important;color:#ffdf94;font:600 12px/16px system-ui!important;white-space:nowrap;text-shadow:0 1px 3px #0009;margin:0!important}.bc-card-starting-price small{font:normal 10px system-ui;color:inherit}.bc-title-priced .catalog-open{margin-top:2px!important}#bcBookStartingPrice{margin:14px 0 18px}#bcBookStartingPrice .bc-book-price{margin:0;display:flex;gap:10px;align-items:baseline;color:#244c3b;font:16px system-ui}#bcBookStartingPrice strong{font:normal 32px Georgia,serif}#bcBookStartingPrice .bc-book-price-note{margin:5px 0 0;font:11px/1.5 system-ui;color:#656b5c}#bcCatalogPriceNote{font:11px/1.5 system-ui;color:#fff0c4;background:#173d30;padding:9px 16px;text-align:center;margin:0}';document.head.append(style);
const fmt=p=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:p[2]}).format(p[1]/100);
function fromPages(n){return n<=60?['express',1190,'USD',n]:n<=120?['short',1390,'USD',n]:n<=350?['pb',1590,'USD',n]:['pb-long',2190,'USD',n];}
function scan(){
 document.querySelectorAll('#catalogGrid .card').forEach(card=>{if(card.querySelector('.bc-card-starting-price'))return;const img=card.querySelector('img');const slug=img?.getAttribute('src')?.split('/').pop()?.replace(/\.[^.]+$/,'');const p=prices[slug];const author=card.querySelector('.author');if(!author)return;const line=document.createElement('span');line.className='bc-card-starting-price';line.setAttribute('translate','no');line.textContent=p?'À partir de '+fmt(p):'Tarif à confirmer';line.title='Tarif de lancement provisoire · édition et livraison à confirmer avant paiement';card.classList.add('bc-title-priced');author.after(line);});
 const grid=document.getElementById('catalogGrid');if(grid&&!document.getElementById('bcCatalogPriceNote')){const note=document.createElement('p');note.id='bcCatalogPriceNote';note.textContent='Éditions imprimées bientôt disponibles · tarifs de lancement provisoires avant taxes, à confirmer selon l’édition et la livraison. La lecture numérique reste gratuite.';const pagination=document.getElementById('catalogPagination');(pagination||grid).after(note);}
 const hero=document.querySelector('main .hero');const info=hero?.children[1];const by=info?.querySelector('.by');if(!by||document.getElementById('bcBookStartingPrice'))return;
 const slug=location.pathname.split('/').filter(Boolean)[1];const pageMatch=info.querySelector('.facts')?.textContent.match(/(\d+)\s*(?:pages|Seiten|páginas)/i);const p=prices[slug]||(pageMatch?fromPages(+pageMatch[1]):null);
 const line=document.createElement('div');line.id='bcBookStartingPrice';line.setAttribute('translate','no');const title=document.createElement('p');title.className='bc-book-price';const label=document.createElement('span');label.textContent=p?'À partir de':'Tarif à confirmer';title.append(label);if(p){const amount=document.createElement('strong');amount.textContent=fmt(p);title.append(amount);}const note=document.createElement('p');note.className='bc-book-price-note';note.textContent='Tarif de lancement provisoire · édition imprimée bientôt disponible · à confirmer avant paiement';line.append(title,note);by.after(line);
}
scan();new MutationObserver(scan).observe(document.querySelector('main')||document.body,{childList:true,subtree:true});
})();

/* Trust block near payment + shipping help link. */
(()=>{'use strict';
const fr=()=>(document.getElementById('uiLangSelect')?.value||document.documentElement.lang||'').toUpperCase().startsWith('FR');
const css=document.createElement('style');css.textContent='.bc-trust{margin:14px 0 0;padding:12px 14px;border:1px solid #d9cfae;border-radius:12px;background:#fbf7ec;color:#213d30;font:13px/1.5 system-ui,sans-serif}.bc-trust ul{list-style:none;margin:0;padding:0;display:grid;gap:5px}.bc-trust li{display:flex;gap:8px;align-items:flex-start}.bc-trust li::before{content:"✓";color:#2f6b4f;font-weight:700;flex:none}.bc-trust a{color:#2f6b4f;font-weight:600}';
document.head.append(css);
function block(){const f=fr();const d=document.createElement('div');d.className='bc-trust';d.setAttribute('translate','no');
const items=f?['Paiement sécurisé par PayPal : carte bancaire acceptée, compte PayPal non obligatoire','Livré ou remboursé : réimpression ou remboursement si le colis n’arrive pas ou arrive abîmé','Envoi suivi : numéro de suivi envoyé par email à l’expédition','Prix affiché tout compris : impression et livraison, sans frais cachés']:['Secure payment with PayPal: pay by card, no PayPal account required','Delivered or refunded: reprint or refund if your parcel does not arrive or arrives damaged','Tracked shipping: tracking number emailed when your book ships','All-in price: printing and delivery included, no hidden fees'];
d.innerHTML='<ul>'+items.map(t=>'<li>'+t+'</li>').join('')+'</ul><p style="margin:8px 0 0"><a href="/shipping.html">'+(f?'Livraison, suivi et remboursement →':'Shipping, tracking & refunds →')+'</a></p>';return d;}
function place(){
 const pay=document.getElementById('bcPrintPay');const box=pay?.parentElement;
 if(box&&!box.nextElementSibling?.classList.contains('bc-trust'))box.after(block());
 const cart=document.getElementById('bcCart');if(cart&&cart.childElementCount&&!cart.querySelector('.bc-trust'))cart.append(block());
 document.querySelectorAll('footer .wrap').forEach(w=>{if(!w.querySelector('a[href="/shipping.html"]')){const a=document.createElement('a');a.href='/shipping.html';a.textContent=fr()?'Livraison':'Shipping';const p=w.querySelector('p');p?p.before(a):w.append(a);}});
}
let q=false;const sched=()=>{if(q)return;q=true;requestAnimationFrame(()=>{q=false;place();});};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',place,{once:true});else place();
new MutationObserver(sched).observe(document.body,{childList:true,subtree:true});
})();

/* Shop text in English when the site language is not French. */
(()=>{'use strict';
const P=[['Collection imprimée en préparation · sélection et estimation de lancement.','Print collection in preparation · launch selection and estimate.'],
['Estimation avant taxes. Le prix et la disponibilité de chaque édition ainsi que la livraison restent à confirmer. Les devises sont présentées séparément. Aucun paiement ni réservation n’est effectué.','Estimate before tax. Price, availability of each edition and delivery are confirmed before payment. No payment or reservation is made.'],
[' Les réductions sont suspendues pour la France dans l’attente de validation des règles du prix du livre.',' Discounts are suspended for France pending validation of book-pricing rules.'],
[' Remise simulée pour une seule commande à une même adresse.',' Simulated discount for a single order to one address.'],
['Votre panier est vide. Ajoutez un livre depuis sa fiche.','Your cart is empty. Add a book from its page.'],
['Livre ajouté à votre sélection. Choisissez l’édition dans le panier.','Book added. Choose the edition in your cart.'],
['Livre ajouté pour cette visite. La sauvegarde sur cet appareil est indisponible.','Book added for this visit. Saving on this device is unavailable.'],
['Votre sélection est conservée sur cet appareil.','Your selection is saved on this device.'],
['Tarif de lancement provisoire · édition imprimée bientôt disponible · à confirmer avant paiement','Provisional launch price · print edition coming soon · confirmed before payment'],
['Tarif de lancement provisoire · édition et livraison à confirmer avant paiement','Provisional launch price · edition and delivery confirmed before payment'],
['Éditions imprimées bientôt disponibles · tarifs de lancement provisoires avant taxes, à confirmer selon l’édition et la livraison. La lecture numérique reste gratuite.','Print editions coming soon · provisional launch prices before tax, confirmed by edition and delivery. Digital reading stays free.'],
['Broché ou relié · format 6 × 9 · mode test','Paperback or hardcover · 6 × 9 · test mode'],
['Paiement groupé en préparation','Combined checkout coming soon'],['Pays de livraison envisagé','Delivery country'],['Pays de livraison','Delivery country'],['Collection envisagée','Edition'],
['Commander le livre','Order the book'],['Ajouter au panier','Add to cart'],['Fermer le panier','Close cart'],['Votre panier','Your cart'],['Choisir un pays','Choose a country'],['Tarif à confirmer','Price to be confirmed'],
['Sous-total indicatif : ','Indicative subtotal: '],['Remise simulée : ','Simulated discount: '],['Réduire la quantité de ','Decrease quantity of '],['Augmenter la quantité de ','Increase quantity of '],['Édition de ','Edition of '],
['Broché court / moyen','Short / medium paperback'],['Broché long','Long paperback'],['Relié classique','Classic hardcover'],['Relié long','Long hardcover'],['Classique express','Express classic'],['Petit classique','Short classic'],['Illustré N&B · broché','B&W illustrated · paperback'],['Illustré N&B · relié','B&W illustrated · hardcover'],['Collector couleur · relié','Colour collector · hardcover'],['Couleur · broché','Colour · paperback'],
['Royaume-Uni','United Kingdom'],['États-Unis','United States'],['Irlande','Ireland'],['Pays-Bas','Netherlands'],['Australie','Australia'],['Allemagne','Germany'],['Espagne','Spain'],['Italie','Italy'],['Danemark','Denmark'],['Estonie','Estonia'],['Nouvelle-Zélande','New Zealand'],['Malaisie','Malaysia'],
[' · à partir de ',' · from '],['À partir de ','From '],['À partir de','From'],['Retirer','Remove']];
const R=[[/(\d+) livres? · remise estimée (\d+) %/g,(m,n,r)=>n+(n==='1'?' book':' books')+' · estimated discount '+r+'%'],[/Ouvrir le panier, (\d+) livres/g,'Open cart, $1 books'],
[/(\d{1,3}(?:[   ]\d{3})*),(\d{2})[   ]?\$US/g,(m,a,b)=>'US$'+a.replace(/[   ]/g,',')+'.'+b]];
const tr=s=>{for(const [a,b] of P)s=s.split(a).join(b);for(const [a,b] of R)s=s.replace(a,b);return s;};
const fr=()=>(document.getElementById('uiLangSelect')?.value||document.documentElement.lang||'').toUpperCase().startsWith('FR');
const SEL='#bcCart,#bcCartOpen,#bcAddCart,#bcCartStatus,#bcBookStartingPrice,.bc-card-starting-price,#bcCatalogPriceNote,#bcPrintDialog,#bcPrint';
const orig=new WeakMap();let busy=false;
function run(){if(busy)return;busy=true;const f=fr();
 document.querySelectorAll(SEL).forEach(root=>{
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
  while((n=w.nextNode())){let o=orig.get(n);if(o===undefined||(n.data!==o&&n.data!==tr(o))){o=n.data;orig.set(n,o);}const v=f?o:tr(o);if(n.data!==v){n.data=v;orig.set(n,o);}}
  [root,...root.querySelectorAll('[aria-label],[title]')].forEach(el=>['aria-label','title'].forEach(a=>{if(!el.hasAttribute(a))return;const k='data-bcfr-'+a;const cur=el.getAttribute(a);let o=el.getAttribute(k);if(o===null||(cur!==o&&cur!==tr(o))){o=cur;el.setAttribute(k,o);}const v=f?o:tr(o);if(el.getAttribute(a)!==v)el.setAttribute(a,v);}));
 });
 busy=false;}
let q=false;const sched=()=>{if(q||busy)return;q=true;requestAnimationFrame(()=>{q=false;run();});};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run();
new MutationObserver(sched).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','title']});
document.addEventListener('change',e=>{if(e.target.id==='uiLangSelect')setTimeout(run,50);});
})();
